def _hora(valor):
    """Devuelve el valor como numero, o None si no se puede leer como hora."""
    if isinstance(valor, bool):
        return None
    if isinstance(valor, (int, float)):
        return float(valor)
    if isinstance(valor, str):
        try:
            return float(valor.strip())
        except (ValueError, TypeError):
            return None
    return None

